16	// Normalize subtitles for LLM/AI SEO extractability:
17	// - Remove HTML
18	// - Replace multiple spaces
19	// - Replace exclamations with periods
20	// - Limit to at most two sentences
21	// - Cap length to ~200 chars, cutting at last space
22	function normalizeSubTitle(input: string): string {
23	  let s = (input || "")
24	    .replace(/<[^>]*>/g, "")
25	    .replace(/\s+/g, " ")
26	    .trim();
27	  if (!s) return s;
28	  s = s.replace(/!/g, ".");
29	
30	  // Limit to two sentences (., ?, !)
31	  const ends: number[] = [];
32	  for (let i = 0; i < s.length; i++) {
33	    const ch = s[i];
34	    if (ch === "." || ch === "?" || ch === "!") ends.push(i);
35	    if (ends.length === 2) break;
36	  }
37	  if (ends.length === 2) {
38	    s = s.slice(0, ends[1] + 1);
39	  }
40	
41	  // Cap length to 200 chars
42	  const MAX_LEN = 200;
43	  if (s.length > MAX_LEN) {
44	    const cut = s.slice(0, MAX_LEN);
45	    const lastSpace = cut.lastIndexOf(" ");
46	    s = (lastSpace > 0 ? cut.slice(0, lastSpace) : cut).trim();
47	    if (!/[.!?]$/.test(s)) s += ".";
48	  }
49	
50	  return s;
51	}
